580: #
581: # -Detach (ROADMAP R12; decisions D1-D12 of its design round): the FOREGROUND - this process, as
582: # the coordinator started it - makes every check a real run makes before it takes the task lock
583: # (the dry run's checks, and the refusals a dry run only reports: the launcher of every engine
584: # that will run, an active recovery record, the preflight - D2), writes the status file once,
585: # state `starting` (Start-DetachedRun), starts the BACKGROUND and exits 0. Not checked in the
586: # foreground: the task lock and the time-dependent health/peak selection - a benign window: the
587: # background is refused then, and its status says so (D3).
588: # The BACKGROUND is `<this host> -File codex-consult.ps1 -Task <t> -CollabDir <absolute> -DetachId
589: # <guid>` in the caller's working directory (D8), its stdout and stderr in the log, started so
590: # that it holds none of the caller's handles: Windows - cmd.exe /c with the redirection, through
591: # ShellExecute, hidden; elsewhere - /bin/sh -c 'exec nohup ...'. Its first action is the self-
592: # report `running` {pid, start_time, host} (D5), then UTF-8 console output (D10), then the
593: # consultation itself IN THIS PROCESS with the foreground's arguments (the `starting` record's
594: # `args`), inside a try/finally that writes the final status {done, exit, summary} whatever the
595: # run did (D3). The run keeps its members' states in the file as they start and finish (D11), and
596: # Stop-WithError records a refusal before it exits ($script:StopWithErrorHook).
597: # -Status / -Wait read status files only (-Prune, the one writing form, deletes old ones): no
598: # lock, no roster, no launcher (D6, D7).
599: 
600: # This script's path (a function of the dot-sourced common file sees THAT file in $PSCommandPath).
601: $script:SelfPath = $PSCommandPath
602: # The parameters of this call (inside a function $PSBoundParameters is the function's own).
603: $script:ScriptBound = @{}
604: foreach ($bk in $PSBoundParameters.Keys) { $script:ScriptBound[$bk] = $PSBoundParameters[$bk] }
605: $script:CommonParameterNames = @([System.Management.Automation.Cmdlet]::CommonParameters) + @([System.Management.Automation.Cmdlet]::OptionalCommonParameters)
606: # The detached run this process is ({ Path; Record }) - set below when -DetachId names it.
607: $script:DetachRun = $null
608: # The summary block a run prints (Write-Summary); a detached run's status file keeps it (D3).
609: $script:SummaryLines = New-Object System.Collections.Generic.List[string]
610: 
611: # One line of the run's summary block: printed, and kept for a detached run's status file.
612: function Write-Summary {
613:     param([string]$Text = '', [string]$Color = '')
614:     if ($Color) { Write-Host $Text -ForegroundColor $Color } else { Write-Host $Text }
615:     $script:SummaryLines.Add($Text)
616: }
617: 
618: # Writes this detached run's status file. Best effort: a status write never stops the run.
619: function Save-DetachedRun {
620:     if (-not $script:DetachRun) { return }
621:     try { Write-DetachedStatus -Path $script:DetachRun.Path -Record $script:DetachRun.Record } catch {
622:         Write-Host "codex-consult: could not update the status file $($script:DetachRun.Path) ($(ConvertTo-OneLine $_.Exception.Message))" -ForegroundColor Yellow
623:     }
624: }
625: 
626: # The members of this detached run - all of them (a panel once its numbers are assigned, a single
627: # run once its reviewer and numbers are known), saved.
628: function Set-DetachedMembers {
629:     param([object[]]$Members)
630:     if (-not $script:DetachRun) { return }
631:     $script:DetachRun.Record.members = [object[]]@($Members | Where-Object { $_ })
632:     Save-DetachedRun
633: }
634: 
635: # Fields of one member of this detached run (by roster position), saved unless -NoSave.
636: function Set-DetachedMember {
637:     param([int]$Position, [hashtable]$Values, [switch]$NoSave)
638:     if (-not $script:DetachRun) { return }
639:     $m = @($script:DetachRun.Record.members | Where-Object { $_ -and [int]$_.position -eq $Position }) | Select-Object -First 1
640:     if (-not $m) { return }
641:     foreach ($k in $Values.Keys) { $m.$k = $Values[$k] }
642:     if (-not $NoSave) { Save-DetachedRun }
643: }
644: 
645: # The run's own final status (D3), right before it exits: done, the exit code, the summary block
646: # it printed (Write-Summary) - else $Line. The background confirms it after the run returned.
647: function Set-DetachedFinal {
648:     param([int]$Exit, [string]$Line = '')
649:     if (-not $script:DetachRun) { return }
650:     $summary = $Line
651:     if ($script:SummaryLines.Count -gt 0) { $summary = $script:SummaryLines.ToArray() -join "`n" }
652:     Complete-DetachedRecord -Record $script:DetachRun.Record -Exit $Exit -Summary $summary
653:     Save-DetachedRun
654: }
655: 
656: # The background's final write (D3), after the run returned or threw: the status file as the run
657: # left it (else $Fallback, the self-report), made final with the run's real exit code.
658: function Complete-DetachedRun {
659:     param([string]$Path, $Fallback, [int]$Exit, [string]$Line = '')
660:     $rec = $Fallback
661:     $rd = Read-DetachedStatus -Path $Path
662:     if ($rd.Record -and [string]$rd.Record.id -eq [string]$Fallback.id) { $rec = $rd.Record }
663:     Complete-DetachedRecord -Record $rec -Exit $Exit -Line $Line
664:     try { Write-DetachedStatus -Path $Path -Record $rec } catch {
665:         Write-Host "codex-consult: could not write the final status to $Path ($(ConvertTo-OneLine $_.Exception.Message))" -ForegroundColor Red
666:     }
667: }
668: 
669: # -Artifact a,b arrives as ONE string through `powershell -File`: each value is split on commas
670: # unless the whole value names an existing file (absolute, or relative to one of $Bases).
671: function Split-ArtifactArgument {
672:     param([string[]]$Values, [string[]]$Bases)
673:     $list = New-Object System.Collections.Generic.List[string]
674:     foreach ($a in @($Values)) {
675:         if (-not $a -or -not $a.Trim()) { continue }
676:         $a = $a.Trim()
677:         $whole = -not $a.Contains(',')
678:         if (-not $whole) {
679:             if ([IO.Path]::IsPathRooted($a)) { $whole = Test-Path -LiteralPath $a -PathType Leaf }
680:             else {
681:                 foreach ($base in $Bases) {
682:                     if (Test-Path -LiteralPath (Join-Path $base $a) -PathType Leaf) { $whole = $true; break }
683:                 }
684:             }
685:         }
686:         if ($whole) { $list.Add($a) }
687:         else { foreach ($piece in $a.Split(',')) { if ($piece.Trim()) { $list.Add($piece.Trim()) } } }
688:     }
689:     return , ([string[]]$list.ToArray())
690: }
691: 
692: # The foreground of -Detach once every check passed (D1, D5, D8): picks the detach id, writes the
693: # `starting` record ONCE, starts the background, prints three lines and exits 0 - or refuses (exit
694: # 1) with nothing left behind. $Members: the planned members (pending; a roster-skipped entry
695: # skipped); $Budget: D4; $Plan: what runs; $BriefFull, $ArtifactFull: absolute (D8); $Warnings:
696: # what a real run prints before it starts. Reads the run's variables ($taskDir, $collabRoot,
697: # $callerCwd, $Task, $Purpose, $ReplyName).
698: function Start-DetachedRun {
699:     param([string]$Kind, [object[]]$Members, [int]$Budget, [string]$Plan, [string]$BriefFull = '', [string[]]$ArtifactFull = @(), [string[]]$Warnings = @())
700:     # The background's arguments: this call's, minus -Detach, with the paths absolute (D8).
701:     $bgArgs = @{}
702:     foreach ($k in $script:ScriptBound.Keys) {
703:         if ($k -eq 'Detach' -or $script:CommonParameterNames -contains $k) { continue }
704:         $bgArgs[$k] = $script:ScriptBound[$k]
705:     }
706:     if ($BriefFull) { $bgArgs['Brief'] = $BriefFull }
707:     if (@($ArtifactFull).Count -gt 0) { $bgArgs['Artifact'] = [string[]]@($ArtifactFull) }
708:     $bgArgs['CollabDir'] = $collabRoot
709:     # The id: a guid whose id8 names no status or log file of the task yet (D7). TEST HOOK:
710:     # CODEX_CONSULT_TEST_DETACH_GUIDS=<guid>[,<guid>...] - tried first, in that order.
711:     $tries = New-Object System.Collections.Generic.List[string]
712:     foreach ($g in ([string]$env:CODEX_CONSULT_TEST_DETACH_GUIDS).Split(',')) {
713:         if ($g.Trim() -match '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') { $tries.Add($g.Trim().ToLowerInvariant()) }
714:     }
715:     for ($i = 0; $i -lt 16; $i++) { $tries.Add([guid]::NewGuid().ToString()) }
716:     try { [void][IO.Directory]::CreateDirectory($taskDir) } catch { Stop-WithError "could not create the task directory '$taskDir' ($(ConvertTo-OneLine $_.Exception.Message)); nothing was started." }
717:     $newId = ''
718:     $paths = $null
719:     foreach ($cand in $tries) {
720:         $p = Get-DetachedPaths -TaskDir $taskDir -Id $cand
721:         if ((Test-Path -LiteralPath $p.Status) -or (Test-Path -LiteralPath $p.Log)) { continue }
722:         $newId = $cand
723:         $paths = $p
724:         break
725:     }
726:     if (-not $newId) { Stop-WithError "no free detach id for task '$Task' (the status or log file of every candidate exists); nothing was started." }
727:     # The background's command line.
728:     $hostExe = (Get-Process -Id $PID).Path
729:     $bgLine = ''
730:     if ($script:OnWindows) {
731:         # cmd.exe would expand a %NAME% in these paths: refused rather than corrupted
732:         foreach ($pth in @($hostExe, $script:SelfPath, $collabRoot, $paths.Log)) {
733:             if ($pth.Contains('%')) { Stop-WithError "-Detach starts its background through cmd.exe, which would expand the '%' in '$pth'; run without -Detach; nothing was started." }
734:         }
735:         $collabArg = $collabRoot
736:         # a trailing backslash would escape the closing quote
737:         if ($collabArg.EndsWith('\')) { $collabArg += '.' }
738:         $inner = '"' + $hostExe + '" -NoProfile -ExecutionPolicy Bypass -File "' + $script:SelfPath + '" -Task ' + $Task + ' -CollabDir "' + $collabArg + '" -DetachId ' + $newId + ' <NUL 1>"' + $paths.Log + '" 2>&1'
739:         $bgLine = '/d /v:off /s /c "' + $inner + '"'
740:     } else {
741:         $q = { param([string]$s) "'" + $s.Replace("'", "'\''") + "'" }
742:         $bgLine = 'exec nohup ' + (& $q $hostExe) + ' -NoProfile -File ' + (& $q $script:SelfPath) + ' -Task ' + (& $q $Task) + ' -CollabDir ' + (& $q $collabRoot) + ' -DetachId ' + $newId + ' </dev/null >' + (& $q $paths.Log) + ' 2>&1'
743:     }
744:     # The `starting` record, written ONCE, before the background exists (D5).
745:     $rec = ConvertTo-DetachedRecord @{
746:         status_version = $script:DetachedStatusVersion; id = $newId; id8 = $paths.Id8; task = $Task; kind = $Kind; state = 'starting'
747:         started = (Get-IsoTimestamp); host = [Environment]::MachineName; budget_sec = $Budget; purpose = $Purpose; reply_name = $ReplyName
748:         brief = $BriefFull; members = [object[]]@($Members | Where-Object { $_ }); log = $paths.Log; args = (ConvertTo-DetachArgs -Arguments $bgArgs)
749:     }
750:     try { Write-DetachedStatus -Path $paths.Status -Record $rec } catch {
751:         Stop-WithError "could not write the status file '$($paths.Status)' ($(ConvertTo-OneLine $_.Exception.Message)); nothing was started."
752:     }
753:     try {
754:         if ($script:OnWindows) {
755:             $cmdExe = [string]$env:ComSpec
756:             if (-not $cmdExe) { $cmdExe = 'cmd.exe' }
757:             # ShellExecute (no -NoNewWindow, no redirection here): the background inherits none of
758:             # this process's handles, so the caller's pipes close when this process exits
759:             $null = Start-Process -FilePath $cmdExe -ArgumentList $bgLine -WorkingDirectory $callerCwd -WindowStyle Hidden -PassThru
760:         } else {
761:             $psi = New-Object System.Diagnostics.ProcessStartInfo
762:             $psi.FileName = '/bin/sh'
763:             [void]$psi.ArgumentList.Add('-c')
764:             [void]$psi.ArgumentList.Add($bgLine)
765:             $psi.UseShellExecute = $false
766:             $psi.WorkingDirectory = $callerCwd
767:             $null = [System.Diagnostics.Process]::Start($psi)
768:         }
769:     } catch {
770:         $why = ConvertTo-OneLine $_.Exception.Message
771:         $rmError = Remove-PendingFile -Path $paths.Status
772:         Stop-WithError "could not start the background process ($why); nothing was started$(if ($rmError) { " (the status file '$($paths.Status)' could not be removed: $rmError)" })."
773:     }
774:     foreach ($w in @($Warnings | Where-Object { $_ })) { Write-Host "WARNING: $w" -ForegroundColor Yellow }
775:     $collabOpt = $(if ($script:ScriptBound.ContainsKey('CollabDir')) { " -CollabDir `"$collabRoot`"" } else { '' })
776:     Write-Host "Detached $($paths.Id8): $Plan - it runs in the background (detach id $newId; budget $Budget s)."
777:     Write-Host "status file: $($paths.Status) (console output: $($paths.Log))"
778:     Write-Host "come back  : codex-consult.ps1 -Task $Task$collabOpt -Status -Id $($paths.Id8) (exit 0 done and usable, 1 a failure, 2 still running); -Wait -Id $($paths.Id8) waits until it is done (default: its budget, $Budget s)"
779:     exit 0
780: }
