7179: # The budget of a detached run (D4) - -Wait's default timeout: per endpoint group ceil(members /
7180: # limit) x the longest member guard of the group, the largest over the groups; with a
7181: # -PanelConcurrency cap also ceil(members / cap) x the longest guard; the larger of the two, plus
7182: # $Slack (120 s). A single run is one group of one member. $Groups: Get-PanelPlan's groups
7183: # (Limit, Positions); $GuardOf: roster position -> that member's kill guard.
7184: function Get-DetachedBudget {
7185:     param([object[]]$Groups, [hashtable]$GuardOf, [int]$Cap = 0, [int]$Slack = 120)
7186:     $byGroups = 0
7187:     $longest = 0
7188:     $count = 0
7189:     foreach ($g in @($Groups | Where-Object { $_ })) {
7190:         $positions = @($g.Positions)
7191:         if ($positions.Count -eq 0) { continue }
7192:         $gMax = 0
7193:         foreach ($p in $positions) { $v = [int]$GuardOf[[int]$p]; if ($v -gt $gMax) { $gMax = $v } }
7194:         $limit = [Math]::Max(1, [int]$g.Limit)
7195:         $waves = [int][Math]::Ceiling($positions.Count / [double]$limit)
7196:         if ($waves * $gMax -gt $byGroups) { $byGroups = $waves * $gMax }
7197:         if ($gMax -gt $longest) { $longest = $gMax }
7198:         $count += $positions.Count
7199:     }
7200:     $byCap = 0
7201:     if ($Cap -gt 0 -and $count -gt 0) { $byCap = [int][Math]::Ceiling($count / [double]$Cap) * $longest }
7202:     return [int]([Math]::Max($byGroups, $byCap) + $Slack)
7203: }
