7101:     $runs = New-Object System.Collections.Generic.List[object]
7102:     if (-not $TaskDir -or -not [IO.Directory]::Exists($TaskDir)) { return , ([object[]]@()) }
7103:     foreach ($f in [IO.Directory]::GetFiles($TaskDir, '.consult.detached-*.status.json')) {
7104:         $name = [IO.Path]::GetFileName($f)
7105:         if ($name -notmatch '^\.consult\.detached-([0-9A-Za-z]+)\.status\.json$') { continue }
7106:         $id8 = $Matches[1].ToLowerInvariant()
7107:         $rd = Read-DetachedStatus -Path $f
7108:         $when = $null
7109:         if ($rd.Record) { $when = ConvertTo-WhenOffset $rd.Record.started }
7110:         if ($null -eq $when) { try { $when = [DateTimeOffset]([IO.File]::GetLastWriteTimeUtc($f)) } catch { $when = [DateTimeOffset]::MinValue } }
7111:         $runs.Add([pscustomobject]@{ Path = $f; Id8 = $id8; Record = $rd.Record; Error = $rd.Error; When = $when; Log = (Join-Path $TaskDir ".consult.detached-$id8.log") })
7112:     }
7113:     $sorted = @($runs | Sort-Object -Property @{ Expression = { $_.When }; Descending = $true }, @{ Expression = { $_.Id8 }; Descending = $false })
7114:     return , ([object[]]$sorted)
7115: }
