7284: # The background's arguments (-Detach) as text for the `starting` record - base64 of UTF-8
7285: # PowerShell CLIXML: PSSerializer keeps every value's type (a -Prompt that looks like a date stays a
7286: # string, an array an array; no command-line quoting is involved) - and back, a hashtable to splat.
7287: # A switch travels as [bool].
7288: function ConvertTo-DetachArgs {
7289:     param([hashtable]$Arguments)
7290:     $clean = @{}
7291:     foreach ($k in @($Arguments.Keys)) {
7292:         $v = $Arguments[$k]
7293:         if ($v -is [System.Management.Automation.SwitchParameter]) { $v = [bool]$v.IsPresent }
7294:         elseif ($v -is [array]) { $v = [string[]]@($v | ForEach-Object { [string]$_ }) }
7295:         $clean[[string]$k] = $v
7296:     }
7297:     $xml = [System.Management.Automation.PSSerializer]::Serialize($clean)
7298:     return [Convert]::ToBase64String($script:Utf8NoBom.GetBytes($xml))
7299: }
